    "POD": [],
}

MAX_IDENTIFIER_LENGTH = 40

_DATE_PATTERNS = (
    (r"\d{4}-\d{2}-\d{2}", "%Y-%m-%d"),
    (r"\d{1,2}/\d{1,2}/\d{4}", "%m/%d/%Y"),
