            "input_tokens": response.usage.input_tokens,
            "output_tokens": response.usage.output_tokens,
            "reasoning_tokens": getattr(output_details, "reasoning_tokens", 0) or 0,
        },
        "latency_seconds": round(latency_seconds, 3),
